package com.codepilot1c.core.edt.debug;
import java.util.*;import java.nio.file.*;import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;
public class DebugTargetSettingsServiceTest {
 @Rule public TemporaryFolder tmp=new TemporaryFolder();
 static class Fake implements DebugTargetSettingsService.Backend{List<String> types=List.of("MANAGED_CLIENT");String epoch="one",app="base";int writes;boolean configurable=true,fail;public Map<String,Object> snapshot(String p,String t){return Map.of("project",p,"target_id",t,"epoch",epoch,"application_id",app,"types",types,"supported_types",List.of("MANAGED_CLIENT","SERVER","JOB"),"configurable",configurable);}public void set(String p,String t,List<String> values){writes++;types=values;if(fail)throw new IllegalStateException("reply lost");}}
 Fake fake;DebugTargetSettingsService service;@Before public void setup()throws Exception{fake=new Fake();service=new DebugTargetSettingsService(tmp.newFolder().toPath(),fake);}
 String apply()throws Exception{var p=service.preview("P","target",List.of("JOB","SERVER"));var r=service.apply("P","target",List.of("JOB","SERVER"),(String)p.get("plan_sha256"));assertEquals("applied",r.get("state"));return (String)r.get("settings_change_id");}
 @Test public void appliesNativeTypesAndRestoresOriginalWithFreshPreview()throws Exception{String id=apply();assertEquals(List.of("JOB","SERVER"),fake.types);var p=service.restorePreview(id);assertEquals("restored",service.restore(id,(String)p.get("plan_sha256")).get("state"));assertEquals(List.of("MANAGED_CLIENT"),fake.types);assertEquals(2,fake.writes);}
 @Test public void manualSettingsChangeIsPreserved()throws Exception{String id=apply();fake.types=List.of("SERVER");assertThrows(IllegalStateException.class,()->service.restorePreview(id));assertEquals(1,fake.writes);}
 @Test public void newTargetEpochOrBaseCannotConsumeOldPreview()throws Exception{var p=service.preview("P","target",List.of("SERVER"));fake.epoch="two";assertThrows(IllegalStateException.class,()->service.apply("P","target",List.of("SERVER"),(String)p.get("plan_sha256")));fake.epoch="one";fake.app="other-base";assertThrows(IllegalStateException.class,()->service.apply("P","target",List.of("SERVER"),(String)p.get("plan_sha256")));assertEquals(0,fake.writes);}
 @Test public void sharedTargetAndUnknownTypeRefuseBeforeSet()throws Exception{assertThrows(IllegalStateException.class,()->service.preview("P","target",List.of("HTTP_SERVICE")));fake.configurable=false;assertThrows(IllegalStateException.class,()->service.preview("P","target",List.of("SERVER")));assertEquals(0,fake.writes);}
 @Test public void unknownWriteCannotBeRetriedWithAnotherReceipt()throws Exception{var p=service.preview("P","target",List.of("SERVER"));fake.fail=true;var r=service.apply("P","target",List.of("SERVER"),(String)p.get("plan_sha256"));assertEquals("outcome_unknown",r.get("state"));assertThrows(IllegalStateException.class,()->service.restorePreview((String)r.get("settings_change_id")));var next=service.preview("P","target",List.of("JOB"));assertThrows(IllegalStateException.class,()->service.apply("P","target",List.of("JOB"),(String)next.get("plan_sha256")));assertEquals(1,fake.writes);}
 @Test public void duplicatesAndUnknownNamesAreRejected()throws Exception{assertThrows(IllegalArgumentException.class,()->DebugTargetSettingsService.types(List.of("SERVER","SERVER")));assertThrows(IllegalArgumentException.class,()->DebugTargetSettingsService.types(List.of("UNKNOWN")));}
 @Test public void noChangeDoesNotWriteOrInventRestoration()throws Exception{var p=service.preview("P","target",fake.types);assertEquals("unchanged",service.apply("P","target",fake.types,(String)p.get("plan_sha256")).get("state"));assertEquals(0,fake.writes);}
}
